import { emitPageLink } from "../pageLink.js";
import { positionalArgs } from "../parseArgs.js";
export function runPageLink() {
    const [path] = positionalArgs([
        { name: "path", description: "Relative Bitfab page path." },
    ]);
    const url = new URL(path, "https://bitfab.invalid");
    const pluginPage = /^\/plugin\/(?:auth\/|sign-in(?:\/|$)|trace-functions\/[^/]+\/template-preview(?:\/|$))/;
    if (!path.startsWith("/") ||
        path.startsWith("//") ||
        path.includes("\\") ||
        url.origin !== "https://bitfab.invalid" ||
        /^\/(?:studio|trace-plan|trace-plans)(?:\/|$)/.test(url.pathname) ||
        (url.pathname.startsWith("/plugin/") && !pluginPage.test(url.pathname))) {
        throw new Error("Provide an app page path or a plugin login or template-preview path.");
    }
    emitPageLink(path);
}
